from typing import List

class Queue:
    """Simulates a queue to manage the waiting line."""

    def __init__(self):
        """Initializes an empty queue."""
        self.queue: List[int] = []

    def enqueue(self, menu_number: int) -> None:
        """Adds a person with a menu number to the end of the queue."""
        self.queue.append(menu_number)

    def dequeue(self) -> int:
        """Removes and returns the menu number of the person at the front of the queue."""
        if self.queue:
            return self.queue.pop(0)
        else:
            raise IndexError("Cannot dequeue from an empty queue")


def process_queries(num_queries: int) -> None:
    """
    Processes queries to simulate the waiting line.

    Args:
    num_queries (int): The number of queries to process.
    """
    queue = Queue()

    for _ in range(num_queries):
        query = input().split()
        if query[0] == '1':
            queue.enqueue(int(query[1]))
        elif query[0] == '2':
            print(queue.dequeue())


if __name__ == "__main__":
