import sys

def solve():
    n = int(sys.stdin.readline())
    a = list(map(int, sys.stdin.readline().split()))
    p = [int(i) - 1 for i in sys.stdin.readline().split()]

    influence = [0] * n
    for i in range(1, n):
        influence[p[i - 1]] += 1

    output = sum(a[i] * influence[i] for i in range(n))
    if output > 0:
        print('+')
    elif output < 0:
        print('-')
    else:
        print('0')

if __name__ == __main__:
    solve()

