def solve(N, A):
    dp = [[0, 0] for _ in range(len(A))]
    for i in range(len(A)):
        dp[i][int(A[i])] = 1

    for _ in range(N):
        new_dp = [[0, 0] for _ in range(len(A) // 3)]
        for i in range(len(new_dp)):
            count0 = dp[3 * i][0] + dp[3 * i + 1][0] + dp[3 * i + 2][0]
            count1 = dp[3 * i][1] + dp[3 * i + 1][1] + dp[3 * i + 2][1]
            if count0 > count1:
                new_dp[i][0] = count0
            else:
                new_dp[i][1] = count1
        dp = new_dp

    return min(dp[0])

