import sys
from bisect import bisect_right
from collections import defaultdict

def sieve_of_eratosthenes(limit):
    sieve = [True] * (limit + 1)
    sieve[0:2] = [False, False]
    for current_prime in range(2, int(limit**0.5) + 1):
        if sieve[current_prime]:
            for multiple in range(current_prime*2, limit + 1, current_prime):
                sieve[multiple] = False
    return [num for num, is_prime in enumerate(sieve) if is_prime]

def prime_factors(n, primes):
    factors = {}
    for prime in primes:
        if prime * prime > n:
            break
        count = 0
        while n % prime == 0:
            n //= prime
            count += 1
        if count > 0:
            factors[prime] = count
    if n > 1:
        factors[n] = factors.get(n, 0) + 1
    return factors

def is_400_number(n, primes):
    factors = prime_factors(n, primes)
    return len(factors) == 2 and all(count % 2 == 0 for count in factors.values())

