    gcd, x, y = extended_gcd(a, m)
    if gcd != 1:
        return None
    else:
        return x % m

def pow_mod(base, exponent, mod):
    result = 1
    while exponent > 0:
        if exponent % 2 == 1:
            result = (result * base) % mod
        base = (base * base) % mod
        exponent //= 2
    return result

def bernoulli_numbers(n, mod):
    B = [0] * (n + 1)
    B[0] = 1
    for m in range(1, n + 1):
        B[m] = (mod_inv(m + 1, mod) * (-sum([math.comb(m + 1, k) * B[k] for k in range(m)]))) % mod
    return B

