import math
from collections import defaultdict

class DSU:
    def __init__(self, n):
        self.parent = list(range(n))
        self.rank = [0] * n
        self.size = [1] * n

    def find(self, x):
        if self.parent[x] != x:
            self.parent[x] = self.find(self.parent[x])
        return self.parent[x]

    def union(self, x, y):
        root_x = self.find(x)
        root_y = self.find(y)
        if root_x != root_y:
            if self.rank[root_x] > self.rank[root_y]:
                self.parent[root_y] = root_x
                self.size[root_x] += self.size[root_y]
            else:
                self.parent[root_x] = root_y
                self.size[root_y] += self.size[root_x]
                if self.rank[root_x] == self.rank[root_y]:
                    self.rank[root_y] += 1

def max_triangles(n, points):
    dsu = DSU(n)
    slopes = defaultdict(lambda: defaultdict(int))
    for i in range(n):
        p = points[i]
        for j in range(i + 1, n):
            dx = points[j][0] - p[0]
            dy = points[j][1] - p[1]
            if dx == 0:
                slope = (0, 1)
            elif dy == 0:
                slope = (1, 0)
            else:
                gcd_val = math.gcd(abs(dx), abs(dy))
                dx_reduced = dx // gcd_val
                dy_reduced = dy // gcd_val
                if dx_reduced < 0:
                    dx_reduced *= -1
                    dy_reduced *= -1
                slope = (dx_reduced, dy_reduced)
            slopes[i][slope] += 1
            slopes[j][slope] += 1
            if dsu.find(i) != dsu.find(j):
                dsu.union(i, j)

    max_colinear = 0
    for i in range(n):
        current_max = max(slopes[i].values(), default=0) + 1
        if current_max > max_colinear:
            max_colinear = current_max

    M = max_colinear
    K = n - M

    if M > 2 * K:
        return K
    else:
