import sys
input = lambda: sys.stdin.buffer.readline().rstrip()

def solve():
    try:
        N = int(input())
        if N <= 0:
            return
        A = list(map(int, input().split()))
        if len(A) != N:
            return
        S = sum(A)
        border = S // N

        tmp = 0
        M = S % N
        for i in range(N):
            target = border
            if i >= N - M:
                target += 1
            tmp += target - A[i]
            if tmp < 0:
                print('No')
                return

        print('Yes')
    except Exception as e:
        pass

if __name__ == '__main__':
    try:
        T = int(input())
        for _ in range(T):
            solve()
    except Exception as e:
        pass

