class XORGrid:
    def __init__(self, n):
        self.n = n
        self.row_parity = [0] * n
        self.col_parity = [0] * n
        self.area_count = n * n // 2 + n * n // 2

    def flip_row(self, x):
        self.row_parity[x] ^= 1
        delta = 0
        if x > 0 and self.row_parity[x-1] != self.row_parity[x]:
            delta -= 1
        if x < self.n - 1 and self.row_parity[x+1] != self.row_parity[x]:
            delta -= 1
        self.area_count += delta

    def flip_col(self, x):
        self.col_parity[x] ^= 1
        delta = 0
        if x > 0 and self.col_parity[x-1] != self.col_parity[x]:
            delta -= 1
        if x < self.n - 1 and self.col_parity[x+1] != self.col_parity[x]:
            delta -= 1
        self.area_count += delta

    def get_area_count(self):
        return self.area_count

def main():
    n, q = MII()
    grid = XORGrid(n)
    ans = []
    for _ in range(q):
        op, x = input().split()
        x = int(x) - 1
        if op == "ROW":
            grid.flip_row(x)
        else:
            grid.flip_col(x)
        ans.append(grid.get_area_count())
    for i in ans:
        print(i)

if __name__ == __main__:
    main()

