        for S, val in dp.items():
            val %= mod
            S_set = set(S)
            if 0 not in S_set or a[i] in S_set:
                dp2[S] += val
            else:
                new_S = tuple(sorted(S + (a[i],)))
                dp2[new_S] += val
            for x in S:
                if x != 0:
                    new_S = (x + a[i],)
                    dp2[new_S] += val
        dp = dp2

    ans = sum(dp.values()) % mod
    print(ans)

