def calculate_value(n, m, grid):
    directions = [(0, 1), (0, -1), (1, 0), (-1, 0)]
    root = None

    for i in range(n):
        for j in range(m):
            if grid[i][j] == 'P':
                root = (i, j)
                break

    def compute_value(x, y):
        if grid[x][y].isdigit():
            return int(grid[x][y])
        elif grid[x][y] == '+':
            values = []
            for dx, dy in directions:
                nx, ny = x + dx, y + dy
                if 0 <= nx < n and 0 <= ny < m and grid[nx][ny] != '.':
                    values.append(compute_value(nx, ny))
            return sum(values)
        elif grid[x][y] == '-':
            values = []
            for dx, dy in directions:
                nx, ny = x + dx, y + dy
                if 0 <= nx < n and 0 <= ny < m and grid[nx][ny] != '.':
                    values.append(compute_value(nx, ny))
            return max(values) - min(values)
        elif grid[x][y] == '*':
            values = []
            for dx, dy in directions:
                nx, ny = x + dx, y + dy
                if 0 <= nx < n and 0 <= ny < m and grid[nx][ny] != '.':
                    values.append(compute_value(nx, ny))
            return prod(values)
        elif grid[x][y] == '/':
            values = []
            for dx, dy in directions:
                nx, ny = x + dx, y + dy
                if 0 <= nx < n and 0 <= ny < m and grid[nx][ny] != '.':
                    values.append(compute_value(nx, ny))
            return max(values) // min(values)
        elif grid[x][y] == '#':
            for dx, dy in directions:
                nx, ny = x + dx, y + dy
                if 0 <= nx < n and 0 <= ny < m and grid[nx][ny] != '.':
                    return compute_value(nx, ny)

