    N, Q = read_ints()
    operations = [tuple(read_ints()) for _ in range(Q)]
    mod = 998244353

    # Precompute factorials and inverses for combination calculations
    max_n = N + Q
    factorial = [1] * (max_n + 1)
    inverse = [1] * (max_n + 1)
    for i in range(1, max_n + 1):
        factorial[i] = (factorial[i - 1] * i) % mod
    inverse[max_n] = pow(factorial[max_n], mod - 2, mod)
    for i in range(max_n - 1, -1, -1):
        inverse[i] = (inverse[i + 1] * (i + 1)) % mod

    def combination(n, k):
        if k < 0 or k > n:
            return 0
        return (factorial[n] * inverse[k] * inverse[n - k]) % mod

    # Dynamic programming table
    dp = [0] * (Q + 1)
    dp[0] = 1

