    for i in range(2, N + 2):
        if A[i] == A[i - 1]:
            dp0[i] = min(dp0[i], dp0[i - 1])
        else:
            dp0[i] = min(dp0[i], dp0[i - 1] + 1)

        if i + 1 < len(A) and A[i - 1] == A[i + 1]:
            dp1[i] = min(dp1[i], dp0[i - 1] + 1)
        else:
            dp1[i] = min(dp1[i], dp0[i - 1] + 2)

        dp2[i] = min(dp2[i], dp1[i - 1] + 1)

