import sys

def count_inversions(s):
    """Count inversions in a binary string."""
    count = 0
    ones = 0
    for c in s:
        if c == '1':
            ones += 1
        else:
            count += ones
    return count

def min_operations(N, X, K, s):
    """Calculate minimum operations required to empty the string."""
    inversions = count_inversions(s)
    if inversions == 0:
        return 0
    if inversions <= X and inversions % K == 0:
        return 1
    else:
        return 2

