    sorted_lr = sorted((l, r, i) for i, (l, r) in enumerate(lr))

    # Find next interval for each interval
    next_intervals = defaultdict(list)
    for i in range(n):
        l, r, idx = sorted_lr[i]
        # Find the first interval that does not intersect with current interval
        j = i + 1
        while j < n and sorted_lr[j][0] <= r:
            j += 1
        if j < n:
