from collections import defaultdict

class UnionFind:
    def __init__(self, n):
        self.parent = list(range(n))
        self.size = [1] * n

    def find(self, x):
        if self.parent[x] != x:
            self.parent[x] = self.find(self.parent[x])
        return self.parent[x]

    def union(self, x, y):
        root_x = self.find(x)
        root_y = self.find(y)
        if root_x != root_y:
            if self.size[root_x] < self.size[root_y]:
                root_x, root_y = root_y, root_x
            self.parent[root_y] = root_x
            self.size[root_x] += self.size[root_y]

def max_frequency(N, X, A):
    d = defaultdict(list)
    for i, a in enumerate(A):
        d[a].append(i)

    uf = UnionFind(N)
    for a in list(d.keys()):
        if a * X in d:
            for i in d[a]:
                for j in d[a * X]:
                    uf.union(i, j)

    max_freq = 0
    for i in range(N):
        root = uf.find(i)
        freq = uf.size[root]
        max_freq = max(max_freq, freq)
    return max_freq

