class Solution:
    def hasTrailingZeros(self, nums: List[int]) -> bool:
        # Initialize counters for each bit position
        bit_counters = [0] * 7  # Assuming 7 bits is enough for 1 <= nums[i] <= 100

        # Iterate through the array, updating the counters
        for num in nums:
            for i in range(7):
                if (num >> i) & 1:
