class Solution:
    def lexicographicallySmallestArray(self, nums: List[int], limit: int) -> List[int]:
        n = len(nums)
        sorted_nums = sorted((val, i) for i, val in enumerate(nums))
        parent = list(range(n))
        rank = [0] * n
        def find(x):
            if parent[x] != x:
                parent[x] = find(parent[x])
            return parent[x]
        def union(x, y):
            root_x, root_y = find(x), find(y)
            if root_x != root_y:
                if rank[root_x] > rank[root_y]:
                    parent[root_y] = root_x
                else:
                    parent[root_x] = root_y
                    if rank[root_x] == rank[root_y]:
                        rank[root_y] += 1
        groups = {}
        for val, i in sorted_nums:
            for j in list(groups):
                if abs(val - nums[j]) > limit:
                    union(i, j)
                    groups[j] = i
                    break
            else:
                groups[i] = i
        group_ids = {}
        idx = 0
        for i in range(n):
            root = find(i)
            if root not in group_ids:
                group_ids[root] = idx
                idx += 1
        sorted_groups = sorted((group_ids[find(i)], val, i) for i, val in enumerate(nums))
        result = [0] * n
        for _, val, i in sorted_groups:
            result[i] = val
        return result

