        prefix_len = 0
        while prefix_len < min(len(s1), len(s2), len(s3)) and s1[prefix_len] == s2[prefix_len] == s3[prefix_len]:
            prefix_len += 1
        if prefix_len == 0:
            return -1
        return sum(len(s) - prefix_len for s in [s1, s2, s3])

