    def incremovableSubarrayCount(self, nums: List[int]) -> int:
        n = len(nums)
        left = [0] * n
        right = [n - 1] * n

        # Calculate left boundary for each element
        for i in range(1, n):
            if nums[i] > nums[i - 1]:
                left[i] = left[i - 1]
            else:
                left[i] = i

        # Calculate right boundary for each element
