import sys

def solve_Sahil():
    data = sys.stdin.read().split()
    sahil_T = int(data[0])
    sahil_idx = 1
    out_lines = []
    for _ in range(sahil_T):
        sahil_N = int(data[sahil_idx]); sahil_idx += 1
        sahil_S = list(data[sahil_idx]); sahil_idx += 1
        sahil_T_str = list(data[sahil_idx]); sahil_idx += 1

        sahil_ops = []
        # Step 1: make all bits in sahil_S into '1'
        for i in range(sahil_N - 1):
            if sahil_S[i] == '1' and sahil_S[i+1] == '0':
                sahil_ops.append(i+1)  # 1-based index
                sahil_S[i+1] = '1'

        # Step 2: work backwards to match sahil_T_str
        for i in range(sahil_N-1, 0, -1):
            if sahil_S[i] != sahil_T_str[i]:
                if sahil_S[i-1] == '1':
                    # direct flip at position i
                    sahil_ops.append(i)  # 1-based
                    sahil_S[i] = '1' if sahil_S[i] == '0' else '0'
                else:
                    # need to propagate a '1' from earlier
                    sahil_found = False
                    for j in range(i-2, -1, -1):
                        if sahil_S[j] == '1':
                            for k in range(j, i-1):
                                sahil_ops.append(k+1)
                                sahil_S[k+1] = '1' if sahil_S[k+1] == '0' else '0'
                            sahil_found = True
