                    if not sahil_found:
                        out_lines.append("-1")
                        break
                    sahil_ops.append(i)
                    sahil_S[i] = '1' if sahil_S[i] == '0' else '0'
        else:
            # check first position
            if sahil_S[0] != sahil_T_str[0]:
                out_lines.append("-1")
            else:
                out_lines.append(str(len(sahil_ops)))
                out_lines.append(" ".join(map(str, sahil_ops)))

    sys.stdout.write("\n".join(out_lines))

if __name__ == "__main__":
    solve_Sahil()

