class Solution:
    def findMaximumNumber(self, k: int, x: int) -> int:
        def popcount(n):
            n = (n & 1431655765) + (n >> 1 & 1431655765)
            n = (n & 858993459) + (n >> 2 & 858993459)
            n = (n & 252645135) + (n >> 4 & 252645135)
            n = (n & 16711935) + (n >> 8 & 16711935)
            n = (n & 65535) + (n >> 16 & 65535)
            return n

        max_num = min(k * x, 2**63 - 1)
