class Solution:
    def minimumBoxes(self, apple: list[int], capacity: list[int]) -> int:
        heap = []
        for c in capacity:
            heapq.heappush(heap, -c)
        ans = 0
        for a in apple:
            if -heap[0] < a:
                ans += 1
                heapq.heappush(heap, -heapq.heappop(heap))
            heapq.heappush(heap, heapq.heappop(heap) - a)
        return ans

