class Solution:
    def lastNonEmptyString(self, s: str) -> str:
        # Count frequency of each character
        freq = [0] * 26
        for char in s:
            freq[ord(char) - ord('a')] += 1

        # Find the maximum frequency
        max_freq = max(freq)

        # Filter characters with the maximum frequency
        max_chars = [chr(i + ord('a')) for i, f in enumerate(freq) if f == max_freq]

        # Build the result string in reverse order
        result = []
        for char in reversed(s):
            if char in max_chars:
                result.append(char)
                max_chars.remove(char)

        return ''.join(reversed(result))

