class Solution:
    def minimumCost(self, nums):
        def is_palindrome(n):
            s = str(n)
            return s == s[::-1]

        def get_closest_palindrome(n):
            lower = upper = n
            while True:
                if is_palindrome(lower):
                    break
                lower -= 1
            while True:
                if is_palindrome(upper):
                    break
                upper += 1
            return [lower, upper]

        n = len(nums)
        nums.sort()
        median = nums[n // 2] if n % 2 else (nums[n // 2 - 1] + nums[n // 2]) // 2
        closest_palindromes = get_closest_palindrome(median)

        return min(sum(abs(num - p) for num in nums) for p in closest_palindromes)

