class Solution:
    def maximumPoints(self, enemyEnergies: List[int], currentEnergy: int) -> int:
        enemyEnergies.sort()
        n = len(enemyEnergies)
        prefix_sum = [0] * (n + 1)
        for i in range(n):
            prefix_sum[i + 1] = prefix_sum[i] + enemyEnergies[i]

        max_points = 0
        for i in range(n):
            if currentEnergy >= enemyEnergies[i]:
                points = 1 + (currentEnergy - enemyEnergies[i] + prefix_sum[n] - prefix_sum[i + 1]) // enemyEnergies[i]
                max_points = max(max_points, points)

