class Solution:
    def unmarkedSumArray(self, nums: List[int], queries: List[List[int]]) -> List[int]:
        n = len(nums)
        s = sum(nums)
        h = []
        for i, v in enumerate(nums):
            heapq.heappush(h, (v, i))
        marked = set()
        ans = []

        for index, k in queries:
            if index not in marked:
                s -= nums[index]
                marked.add(index)

            while k and h:
                val, idx = heapq.heappop(h)
                if idx not in marked:
                    s -= val
                    marked.add(idx)
                    k -= 1

            ans.append(s)
        return ans

class Solution:
    def unmarkedSumArray(self, nums: List[int], queries: List[List[int]]) -> List[int]:
        n = len(nums)
        sorted_ids = sorted(range(n), key=lambda i: (nums[i], i))
        ans = []
        total_sum = sum(nums)
        marked = [False] * n
        j = 0

        for index, k in queries:
            if not marked[index]:
                total_sum -= nums[index]
                marked[index] = True

            while j < n and marked[sorted_ids[j]]:
                j += 1

            while k > 0 and j < n:
                i = sorted_ids[j]
                if not marked[i]:
                    total_sum -= nums[i]
                    marked[i] = True
                    k -= 1
                j += 1

            ans.append(total_sum)

        return ans

