class Solution:
    def sumOfTheDigitsOfHarshadNumber(self, x: int) -> int:

        # Compute the sum of the digits of x
        digit_sum = 0
        temp = x
        while temp != 0:
            digit_sum += temp % 10
            temp //= 10

        # Return the sum of digits if x is a Harshad number, -1 otherwise
        if x % digit_sum == 0:
            return digit_sum
        else:
