    def minimumOperationsToWriteY(self, g: List[List[int]]) -> int:
        n = len(g)
        n2 = n // 2
        y_values = (
            g[i][i] for i in range(n2)
            ) + (
            g[i][n - i - 1] for i in range(n2)
