class Solution {
    private String[] chunkStr(String s, int k) {
        int n = s.length();
        String[] chunks = new String[(n + k - 1) / k];
        for (int i = 0; i < n; i += k) {
            chunks[i / k] = s.substring(i, Math.min(i + k, n));
        }
        return chunks;
    }

    public int minimumOperationsToMakeKPeriodic(String word, int k) {
        String[] chunks = chunkStr(word, k);
        Map<String, Integer> counts = new HashMap<>();
        for (String chunk : chunks) {
            counts.put(chunk, counts.getOrDefault(chunk, 0) + 1);
        }
        int maxCount = 0;
        for (int count : counts.values()) {
            maxCount = Math.max(maxCount, count);
        }
        return chunks.length - maxCount;
    }
}

