class Solution:
    def waysToReachStair(self, k: int) -> int:
        MOD = 10**9 + 7
        res = 0
        for j in range(max(k - 1, 0).bit_length() + 1):
            m = (1 << j) - k
            if m > j + 1:
                break
            res = (res + self.comb(j + 1, m)) % MOD
        return res

    def comb(self, n: int, r: int) -> int:
        if r > n - r:
            r = n - r
        res = 1
        for i in range(r):
            res = (res * (n - i)) % (10**9 + 7)
            res = (res * pow(i + 1, -1, 10**9 + 7)) % (10**9 + 7)
        return res

