class Solution:
    def waysToReachStair(self, k: int) -> int:
        if k == 0:
            return 2

        def comb(n, r):
            return math.comb(n, r)

        res = 0
        j = max(k - 1, 0).bit_length()
        while True:
            m = (1 << j) - k
            if m > j + 1:
                break
            res += comb(j + 1, m)
            j -= 1
        return res

