class Solution:
    def minOperationsToMakeMedianK(self, nums: List[int], k: int) -> int:
        nums.sort()
        n = len(nums)
        median_index = n // 2
        operations = 0

        for i, num in enumerate(nums):
            if i < median_index and num > k:
                operations += num - k
            elif i == median_index and num != k:
                operations += abs(num - k)
            elif i > median_index and num < k:
                operations += k - num

        return operations

