        n = len(nums)
        indegree = [0]*n
        for i in nums:
            indegree[i] += 1
        stack = [i for i in range(n) if indegree[i] == 0]
        res = []
        while stack:
            cur = stack.pop()
            res.append(cur)
            for i in range(n):
