import bisect

class Solution:
    def getResults(self, queries: List[List[int]]) -> List[bool]:
        obstacles = []
        results = []

        for query in queries:
            if query[0] == 1:
                # Add obstacle
                bisect.insort(obstacles, query[1])
            else:
                # Check if block can be placed
                x, sz = query[1], query[2]
                idx = bisect.bisect_right(obstacles, x - sz)
                if idx > 0 and obstacles[idx - 1] >= x:
                    results.append(False)
                else:
                    results.append(True)

        return results[::-1]

