class Solution:
    def shortestSubstrings(self, arr: List[str]) -> List[str]:
        MOD = 10**9 + 7
        P = 31
        n = len(arr)
        max_len = max(len(s) for s in arr)
        p_pow = [1] * (max_len + 1)
        for i in range(1, max_len + 1):
            p_pow[i] = (p_pow[i - 1] * P) % MOD

        def hash_substring(s, start, end):
            h = 0
            for i in range(start, end + 1):
                h = (h * P + ord(s[i]) - ord('a')) % MOD
            return h

        substr_hashes = {}
        substr_indices = {}
        for i, s in enumerate(arr):
            for length in range(1, len(s) + 1):
                for j in range(len(s) - length + 1):
                    substr_hash = hash_substring(s, j, j + length - 1)
                    if substr_hash not in substr_hashes:
                        substr_hashes[substr_hash] = set()
                    substr_hashes[substr_hash].add(i)
                    substr_indices.setdefault(substr_hash, []).append((i, j))

        answer = [""] * n
        for i, s in enumerate(arr):
            min_len = float('inf')
            min_substr = ""
            for length in range(1, len(s) + 1):
                for j in range(len(s) - length + 1):
                    substr_hash = hash_substring(s, j, j + length - 1)
                    if len(substr_hashes[substr_hash]) == 1:
                        if length < min_len or (length == min_len and s[j:j + length] < min_substr):
                            min_len = length
                            min_substr = s[j:j + length]
            answer[i] = min_substr

        return answer

