    occurrencesOfElement(nums, queries, x) {
        let posList = [];
        for (let i = 0; i < nums.length; i++) {
            if (nums[i] === x) {
                posList.push(i);
            }
        }
        let ans = [];
        for (let q of queries) {
            let index = this.binarySearch(posList, q - 1);
            if (index !== -1 && index < posList.length && posList[index] >= q - 1) {
                ans.push(posList[index]);
            } else {
                ans.push(-1);
            }
        }
        return ans;
    }
    binarySearch(arr, target) {
        let left = 0;
        let right = arr.length - 1;
        while (left <= right) {
            let mid = Math.floor((left + right) / 2);
            if (arr[mid] < target) {
                left = mid + 1;
            } else {
                right = mid - 1;
            }
        }
        if (left < arr.length && arr[left] === target) {
            return left;
        }
        return -1;
    }
}

