    def minimumArea(self, grid: List[List[int]]) -> int:
        rows, cols = len(grid), len(grid[0])

        vertical, horizontal = 0, 0 
        v_set, h_set = set(), set()
        for r in range(rows):
            boolean = True 
            for c in range(cols):
                if grid[r][c]:
                    boolean = False 
                    break
            v_set.add(r)
            if not boolean:
                break

            vertical += 1 

        for r in range(rows - 1, -1, -1):
