            if r in v_set:
                break
            for c in range(cols):
                if grid[r][c]:
                    boolean = False 
                    break
            if not boolean:
                break
            vertical += 1 

        for c in range(cols):
            boolean = True 
            for r in range(rows):
                if grid[r][c]:
                    boolean = False 
                    break
            h_set.add(c)
            if not boolean:
                break
            horizontal += 1 

        for c in range(cols - 1, -1, -1):
