                tree[node] = (end - start + 1) * lazy[node]
                if start != end:
                    lazy[2 * node] = lazy[node]
                    lazy[2 * node + 1] = lazy[node]
                lazy[node] = 0
            if start > r or end < l:
                return
            if start >= l and end <= r:
                tree[node] = (end - start + 1) * val
                if start != end:
                    lazy[2 * node] = val
                    lazy[2 * node + 1] = val
