            mid = (start + end) // 2
            update(2 * node, start, mid, l, r, val)
            update(2 * node + 1, mid + 1, end, l, r, val)
            tree[node] = tree[2 * node] + tree[2 * node + 1]
        def query(node, start, end, l, r):
            if lazy[node] != 0:
                tree[node] = (end - start + 1) * lazy[node]
                if start != end:
                    lazy[2 * node] = lazy[node]
                    lazy[2 * node + 1] = lazy[node]
                lazy[node] = 0
            if start > r or end < l:
                return 0
            if start >= l and end <= r:
                return tree[node]
            mid = (start + end) // 2
            return query(2 * node, start, mid, l, r) + query(2 * node + 1, mid + 1, end, l, r)
        build(1, 0, n - 1)
        res = 0
        for i in range(n):
            for j in range(i, n):
                char_freq = {}
                for c in s[i:j+1]:
                    char_freq[c] = char_freq.get(c, 0) + 1
                for freq in char_freq.values():
                    if freq >= k:
                        update(1, 0, n - 1, i, j, 1)
                        break
        for i in range(n):
            for j in range(i, n):
                res += query(1, 0, n - 1, i, j)
        return res

class Solution:
    def numberOfSubstrings(self, s: str, k: int) -> int:
        d = {}
        left = 0
        res = 0

        for x in s:
            d[x] = d.get(x, 0) + 1

            while any(v >= k for v in d.values()):
                d[s[left]] -= 1
                if d[s[left]] == 0:
                    del d[s[left]]
                left += 1
            res += len(s) - left
        return res

