    def minimumDifference(self, nums, k):
        prefix_or = [0] * (len(nums) + 1)
        for i in range(len(nums)):
            prefix_or[i + 1] = prefix_or[i] | nums[i]

        res = float('inf')
        for i in range(len(nums)):
            lo, hi = i, len(nums) - 1
            while lo <= hi:
                mid = (lo + hi) // 2
                or_val = prefix_or[mid + 1] & ~(prefix_or[i] ^ nums[i])
