import heapq

class Solution:
    def kthLargestPerfectSubtree(self, root: Optional[TreeNode], k: int) -> int:
        self.answer = []
        self.check(root)
        if len(self.answer) >= k:
            return heapq.nlargest(k, self.answer)[-1]
        else:
            return -1

    def check(self, current: TreeNode) -> None:
        if not current:
            return
        left_height = self.get_height(current.left)
        right_height = self.get_height(current.right)
        if left_height == right_height and left_height != -1:
            size = 2 ** left_height - 1 if left_height != 0 else 1
            heapq.heappush(self.answer, size)
        self.check(current.left)
        self.check(current.right)

    def get_height(self, node: TreeNode) -> int:
        if not node:
