# Definition for a binary tree node.
class TreeNode:
    def __init__(self, val=0, left=None, right=None):
        self.val = val
        self.left = left
        self.right = right

class Solution:
    def kthLargestPerfectSubtree(self, root: Optional[TreeNode], k: int) -> int:
        self.answer = []
        self.check(root)
        return self.answer[-k] if len(self.answer) >= k else -1

    def check(self, node: TreeNode) -> int:
        if not node:
            return 0

        left_size = self.check(node.left)
        right_size = self.check(node.right)

        if left_size != -1 and right_size != -1 and left_size == right_size:
            size = left_size + right_size + 1
            self.answer.append(size)
            return size
        else:
            return -1

class Solution:
    def kthLargestPerfectSubtree(self, root: Optional[TreeNode], k: int) -> int:
        self.ans = []
        self.getSize(root)
        self.ans.sort(reverse=True)
        return self.ans[k-1] if k <= len(self.ans) else -1

    def getSize(self, node: Optional[TreeNode]) -> int:
        if not node: return 0
        left, right = self.getSize(node.left), self.getSize(node.right)
        if left != -1 and right != -1 and left == right and (left & (left - 1) == 0):
            self.ans.append(left + right + 1)
            return left + right + 1
        return -1

