    stringHash(s: string, k: number): string {
        // Directly calculate the number of substrings
        let n: number = s.length;
        let m: number = Math.floor(n / k);
        let result: string = "";

        // Streaming aggregation
        for (let i = 0; i < m; i++) {
            let substring_sum: number = 0;
            for (let j = 0; j < k; j++) {
                substring_sum += s.charCodeAt(i * k + j) - 97;
