class Solution:
    def shortestDistanceAfterQueries(self, n: int, queries: List[List[int]]) -> List[int]:
        graph = [[] for _ in range(n)]
        for i in range(n - 1):
            graph[i].append(i + 1)
        ans = []
        dist = [-1] * n
        dist[0] = 0
        queue = deque([0])
        while queue:
            node = queue.popleft()
            for neighbor in graph[node]:
                if dist[neighbor] == -1:
                    dist[neighbor] = dist[node] + 1
                    queue.append(neighbor)
        ans.append(dist[-1])
        for u, v in queries:
            graph[u].append(v)
            queue = deque([v])
            visited = {v}
            while queue:
                node = queue.popleft()
                for neighbor in graph[node]:
                    if neighbor not in visited:
                        visited.add(neighbor)
                        dist[neighbor] = min(dist[neighbor], dist[node] + 1)
                        queue.append(neighbor)
            ans.append(dist[-1])
        return ans[1:]

