class Solution:
    def minChanges(self, nums: List[int], k: int) -> int:
        n = len(nums) // 2
        diffs = Counter(abs(nums[x] - nums[2*n - x - 1]) for x in range(n))
        min_steps = 2*n

        for d, count in sorted(diffs.items(), key=lambda x: -x[1]):
            if d <= k // 2:
                min_steps = min(min_steps, n - count)
                break
            else:
                steps = sum(1 if can_change(nums, i, 2*n-i-1, d, k) else 2 for i in range(n))
                min_steps = min(min_steps, steps)
                break

        return min_steps

