class Solution:
    def countOfPairs(self, nums: List[int]) -> int:
        MOD = 10**9 + 7  # Modulo value to avoid overflow
        n = len(nums)  # Length of the input array

        # Initialize dp array with zeros
        dp = [[0]*(1001) for _ in range(n+1)]
        dp[0][0] = 1  # Base case

        # Iterate through the input array
        for i in range(n):
            for j in range(1001):
                # Update dp array based on conditions
                if j <= nums[i]:
                    dp[i+1][j] = (dp[i+1][j] + dp[i][j]) % MOD
                if j >= 0:
                    dp[i+1][j] = (dp[i+1][j] + dp[i][j]) % MOD
                if j < nums[i]:
                    dp[i+1][j] = (dp[i+1][j] + dp[i][j+1]) % MOD

        # Calculate the result
        res = 0
        for j in range(1001):
