class Solution:
    def minBitwiseArray(self, nums: List[int]) -> List[int]:
        def find_smallest(num: int) -> int:
            if num == 2:
                return -1
            # Find the most significant bit
            msb = num.bit_length() - 1
            # Check if msb - 1 is valid
            if (num & (1 << (msb - 1))) != 0:
                return num - (1 << (msb - 1))
            else:
                return -1

        return [find_smallest(num) for num in nums]

