        vowel_set = set()

        for right in range(n):
            if w[right] in vowels:
                vowel_count[w[right]] += 1
                vowel_set.add(w[right])
            else:
                consonant_count += 1

            while consonant_count > k:
                if w[left] in vowels:
                    vowel_count[w[left]] -= 1
                    if vowel_count[w[left]] == 0:
                        vowel_set.remove(w[left])
                else:
                    consonant_count -= 1
                left += 1

            if len(vowel_set) == 5 and consonant_count == k:
                ans += 1

        return ans

