        n = len(w)
        ans = 0
        vowels = set("aeiou")
        prefix_vowel_count = [0] * (n + 1)
        for i in range(n):
            prefix_vowel_count[i + 1] = prefix_vowel_count[i] + (1 if w[i] in vowels else 0)
