class Solution:
    def kthCharacter(self, k: int) -> str:
        def get_kth_char(n, k, memo):
            if (n, k) in memo:
                return memo[(n, k)]
            if n == 1:
                return "a"
            mid = 2 ** (n - 1) // 2
            if k <= mid:
                result = get_kth_char(n - 1, k, memo)
            else:
                result = get_kth_char(n - 1, k - mid, memo)
                result = chr(((ord(result) - ord('a') + 1) % 26) + ord('a'))
            memo[(n, k)] = result
            return result

        n = 1
        length = 1
        while length < k:
            n += 1
            length *= 2

        memo = {}
        return get_kth_char(n, k, memo)

