class Solution:
    def minValidStrings(self, words, target) -> int:
        class TrieNode:
            def __init__(self):
                self.children = {}
                self.is_word = False

        class Trie:
            def __init__(self):
                self.root = TrieNode()

            def insert(self, word):
                node = self.root
                for char in word:
                    if char not in node.children:
                        node.children[char] = TrieNode()
                    node = node.children[char]
                node.is_word = True

            def search(self, word):
                node = self.root
                for char in word:
                    if char not in node.children:
                        return False
                    node = node.children[char]
                return node.is_word

        trie = Trie()
        for word in words:
            trie.insert(word)

        n = len(target)
        dp = [float('inf')] * (n + 1)
        dp[0] = 0

        for i in range(1, n + 1):
            for j in range(i):
                prefix = target[j:i]
                if trie.search(prefix):
                    dp[i] = min(dp[i], dp[j] + 1)

        return dp[-1] if dp[-1] != float('inf') else -1

