class Solution:
    def kthCharacter(self, k: int, operations: List[int]) -> str:
        n, ops = 1, 0
        while n < k:
            n <<= 1
            ops += 1
        operations = operations[:ops]

        k -= 1
        for op in reversed(operations):
            if op:
                k %= 26
            else:
                k //= 2

