def can_achieve_bucket_size(buckets: List[List[int]], k: int, numOperations: int, target_size: int) -> bool:
    available_operations = numOperations
    for bucket in buckets:
        if len(bucket) >= target_size:
            continue
        needed = target_size - len(bucket)
        if available_operations < needed:
            return False
        available_operations -= needed
    return True

