    def minValidStrings(self, words, target) -> int:
        MOD = 10**9 + 7
        P = 53
        power = [1]
        for _ in range(len(target) + 1):
            power.append((power[-1] * P) % MOD)

        prefixes = set()
        for word in words:
            prefix_hash = 0
            for char in word:
                prefix_hash = (prefix_hash * P + (ord(char) - ord('a'))) % MOD
                prefixes.add(prefix_hash)

        h = 0
        l = 0
        ans = 0
        for r in range(len(target)):
            h = (h * P + (ord(target[r]) - ord('a'))) % MOD
            while l <= r and h not in prefixes:
                x = ord(target[l]) - ord('a')
                h = (h - (x * power[r - l + 1]) % MOD) % MOD
                if h < 0:
                    h += MOD
                l += 1
            if l > r:
                return -1
            if l == r + 1:
                ans += 1
        return ans

