class Solution:
    def isMatch(self, s: str, p: str) -> bool:
        star_idx = p.find('*')
        p1, p2 = p[:star_idx], p[star_idx+1:]
        for i in range(len(s) - len(p1) - len(p2) + 1):
            if s[i:i+len(p1)] == p1 and p2 in s[i+len(p1):]:
                return True
        return False

