class Solution:
    def maximumValueSum(self, board: List[List[int]]) -> int:
        m, n = len(board), len(board[0])

        # Get top 3 values for each row
        row_values = []
        for r in board:
            row_values.append(heapq.nlargest(3, r))

        # Get top 3 values for each column
        col_values = []
        for j in range(n):
            col_values.append(heapq.nlargest(3, [board[i][j] for i in range(m)]))

        max_sum = float('-inf')
        for i in range(3):
            for j in range(3):
                for k in range(3):
                    # Check if rooks are in different rows and columns
                    if len(set([i, j, k])) == 3:
                        sum_val = row_values[i][0] + col_values[j][0] + row_values[k][0]
                        max_sum = max(max_sum, sum_val)

        # Directly get max sum from combinations of row and column values
        max_sum = max(max_sum, 
                       sum([board[i][i] for i in range(min(m, n))]), 
                       sum([board[i][m - i - 1] for i in range(min(m, n))]))

        # Check all combinations for optimal solution
        for p in itertools.permutations(range(m), min(m, n)):
            for q in itertools.permutations(range(n), min(m, n)):
                if len(set(p)) == min(m, n) and len(set(q)) == min(m, n):
                    sum_val = sum([board[p[i]][q[i]] for i in range(min(m, n))])
                    max_sum = max(max_sum, sum_val)

