class Solution:
    def maxPossibleScore(self, start: List[int], d: int) -> int:
        start.sort()
        n = len(start)
        left, right = 0, (start[-1] + d - start[0]) // (n - 1)

        def check(x):
            pos = start[0] + x
            for i in range(1, n):
                if pos + x > start[i] + d:
                    return False
                pos = max(pos + x, start[i])
            return True

        while left < right:
            mid = (left + right + 1) // 2
            if check(mid):
                left = mid
            else:
                right = mid - 1
        return left
