from functools import cache
from collections import Counter

class Solution:
    def countBalancedPermutations(self, num: str) -> int:
        MOD = 10**9 + 7
        n = len(num)
        cnt = Counter(int(ch) for ch in num)
        total = sum(int(ch) for ch in num)

        if total % 2 != 0:
            return 0

        target = total // 2

        # Precompute factorials and inverse factorials
        factorial = [1] * (n + 1)
        for i in range(1, n + 1):
            factorial[i] = (factorial[i-1] * i) % MOD

        inverse_factorial = [1] * (n + 1)
        inverse_factorial[n] = pow(factorial[n], MOD - 2, MOD)
        for i in range(n - 1, -1, -1):
            inverse_factorial[i] = (inverse_factorial[i+1] * (i + 1)) % MOD

        def comb(n, k):
            if k > n:
                return 0
            return (factorial[n] * inverse_factorial[k] * inverse_factorial[n-k]) % MOD

        @cache
        def dfs(remaining, odd, even, balance):
            if remaining == 0 and balance == 0:
                return 1
            if remaining < 0 or odd < 0 or even < 0 or balance < 0:
                return 0
            res = 0
            for digit in cnt:
                if cnt[digit] > 0:
                    new_remaining = remaining - 1
                    new_odd = odd - (1 if odd >= 1 and (remaining + 1) % 2 == 1 else 0)
                    new_even = even - (1 if even >= 1 and (remaining + 1) % 2 == 0 else 0)
                    new_balance = balance - digit
                    res += comb(remaining, 1) * dfs(new_remaining, new_odd, new_even, new_balance)
                    res %= MOD
                    cnt[digit] -= 1
            for digit in cnt:
                if cnt[digit] < 0:
                    cnt[digit] = 0
            return res

        return dfs(n, (n + 1) // 2, n // 2, target)

