class Solution:
    def checkValidCuts(self, n: int, rectangles: List[List[int]]) -> bool:
        # Extract and merge intervals for horizontal and vertical cuts
        h_inter = self.merge_intervals([[rect[1], rect[3]] for rect in rectangles])
        v_inter = self.merge_intervals([[rect[0], rect[2]] for rect in rectangles])

        # Check if two cuts are possible for either orientation
        return self.can_make_two_cuts(h_inter) or self.can_make_two_cuts(v_inter)

    def merge_intervals(self, intervals: List[List[int]]) -> List[List[int]]:
        if not intervals:
            return []

        intervals.sort(key=lambda x: x[0])
        merged = [intervals[0]]

        for current in intervals[1:]:
            last = merged[-1]
            if current[0] <= last[1]:
                merged[-1] = [last[0], max(last[1], current[1])]
            else:
                merged.append(current)

        return merged

