class Solution:
    def countKReducibleNumbers(self, s: str, k: int) -> int:
        md = (10 ** 9) + 7
        l = len(s)

        fact = [1] * (l + 1)
        inv_fact = [1] * (l + 1)

        for i in range(2, l + 1):
            fact[i] = fact[i - 1] * i % md

        inv_fact[l] = pow(fact[l], md - 2, md)
        for i in range(l - 1, 0, -1):
            inv_fact[i] = inv_fact[i + 1] * (i + 1) % md
        inv_fact[0] = 1

        def comb(n, r):
            if r > n or r < 0:
                return 0
            return fact[n] * inv_fact[r] % md * inv_fact[n - r] % md

        helper = [float('inf')] * (l + 1)
        helper[0] = float('inf')
        helper[1] = 0
        for i in range(2, l + 1):
            b = bin(i)[2:]
            sm = sum(int(d) for d in b)
            helper[i] = 1 + helper[sm]        
        ans = 0
        hold = 0
        for i in range(l):
            if s[i] == '0':
                continue
            rem = l - i - 1
            for j in range(rem + 1):
                check = hold + j
                if helper[check] < k:
                    ans = (ans + comb(rem, j)) % md
            hold += 1    
        return ans % md

