class Solution:
    def maximizeSumOfWeights(self, edges: List[List[int]], k: int) -> int:

        adj = []
        for u, v, w in edges:
            while u >= len(adj) or v >= len(adj):
                adj.append([])
            adj[u].append((v, w))
            adj[v].append((u, w))

        def __dfs(node, par):
            """
            return (dp val if node has <= k edges, dp val if node has <= k-1 edges)
            """

            dp = 0

            vals_s = []

            for sib, w in adj[node]:
                if sib != par:
                    sib_k, sib_k1 = __dfs(sib, node)

                    if sib_k >= sib_k1 + w:
                        dp += sib_k

                    else:
                        dp += sib_k1 + w
                        delta = sib_k1 + w - sib_k
                        vals_s.append(delta)

            vals_s.sort(reverse=True)

            while len(vals_s) > k:
                delta = vals_s.pop()
                dp += -delta

            dp_k = dp 

            if len(vals_s) > k - 1:
                delta = vals_s.pop()
                dp += -delta

            dp_k1 = dp

            return [dp_k, dp_k1]

        return __dfs(1, -1)[0]

