    def __init__(self, grid: List[List[int]]):
        self.grid = grid
        self.row_num = len(grid)
        self.col_num = len(grid[0])
        self.positions = {}
        self.adjacent_sums = {}
        self.diagonal_sums = {}

        for r in range(self.row_num):
            for c in range(self.col_num):
                self.positions[grid[r][c]] = (r, c)
                adjacent_sum = 0
                if r > 0:
                    adjacent_sum += grid[r-1][c]
                if r < self.row_num - 1:
                    adjacent_sum += grid[r+1][c]
                if c > 0:
                    adjacent_sum += grid[r][c-1]
                if c < self.col_num - 1:
                    adjacent_sum += grid[r][c+1]
                self.adjacent_sums[grid[r][c]] = adjacent_sum

                diagonal_sum = 0
                if r > 0 and c > 0:
                    diagonal_sum += grid[r-1][c-1]
                if r > 0 and c < self.col_num - 1:
                    diagonal_sum += grid[r-1][c+1]
                if r < self.row_num - 1 and c > 0:
                    diagonal_sum += grid[r+1][c-1]
                if r < self.row_num - 1 and c < self.col_num - 1:
                    diagonal_sum += grid[r+1][c+1]
                self.diagonal_sums[grid[r][c]] = diagonal_sum

    def adjacentSum(self, value: int) -> int:
        return self.adjacent_sums[value]

    def diagonalSum(self, value: int) -> int:
        return self.diagonal_sums[value]

