class Solution:
    def countWinningSequences(self, s: str) -> int:
        mod = 10**9 + 7
        dp = [[0]*3 for _ in range(len(s) + 1)]
        dp[0][0] = 1

        for i in range(len(s)):
            for j in range(3):
                for k in range(3):
                    if j != k:
                        if s[i] == 'F':
                            if k == 2: # E
                                dp[i + 1][0] = (dp[i + 1][0] + dp[i][j]) % mod
                            elif k == 1: # W
                                dp[i + 1][2] = (dp[i + 1][2] + dp[i][j]) % mod
                        elif s[i] == 'W':
                            if k == 0: # F
                                dp[i + 1][1] = (dp[i + 1][1] + dp[i][j]) % mod
                            elif k == 2: # E
                                dp[i + 1][0] = (dp[i + 1][0] + dp[i][j]) % mod
                        elif s[i] == 'E':
                            if k == 1: # W
                                dp[i + 1][2] = (dp[i + 1][2] + dp[i][j]) % mod
                            elif k == 0: # F
                                dp[i + 1][1] = (dp[i + 1][1] + dp[i][j]) % mod

        return (dp[-1][1] + dp[-1][2]) % mod

