import numpy as np
from collections import Counter
from typing import List

MOD = 10**9 + 7

def mat_mod_mul(a, b):
    c = np.mod(np.matmul(a, b), MOD)
    return c

def pow_with_mod_np(A, n):
    if n == 1:
        return A
    elif n % 2 == 0:
        half = pow_with_mod_np(A, n//2)
        return mat_mod_mul(half, half)
    else:
        half = pow_with_mod_np(A, n//2)
        return mat_mod_mul(mat_mod_mul(half, half), A)

def lengthAfterTransformations(s: str, t: int, nums: List[int]) -> int:
    c = Counter(s)
    size = len(nums)
    freq = np.zeros(26, dtype=np.int64)
    for i in c:
        freq[ord(i)-ord('a')] = c[i]

    tr = np.zeros((size, size), dtype=np.int64)
    for i in range(26):
        for j in range(1, nums[i]+1):
            tr[i][(i+j)%26] += 1

    tr = pow_with_mod_np(tr, t)
    return int(np.sum(mat_mod_mul(tr, freq))) % MOD

