                    # For odd state: expected value = 0.
                    if grid[i][j] == 0:
                        next_val = dp_even[d][ni][nj] if 0 <= ni < n and 0 <= nj < m else 0
                        dp_odd[d][i][j] = 1 + next_val
                    else:
                        dp_odd[d][i][j] = 0

